<?php
session_start();
require_once "../config/db.php";
require_once "../includes/auth_check.php";
$role=$_SESSION['role']??'';$user_id=(int)($_SESSION['user_id']??0);
if(!in_array($role,['super_admin','inventory_admin','manager','technician'],true)) die("Access denied.");
$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
$model=trim($_POST['model']??'');$serial=trim($_POST['serial_number']??'');$cargo=trim($_POST['cargo_number']??'');$issue=trim($_POST['issue']??'');$place=trim($_POST['place']??'');$shop=trim($_POST['shop']??'');
if($model==='')$error='Model is required.';elseif($serial==='')$error='Serial number is required.';elseif($shop==='')$error='Shop is required.';else{$dup=$conn->prepare("SELECT 1 FROM faulty_devices WHERE serial_number=:serial AND status='Faulty' LIMIT 1");$dup->execute(['serial'=>$serial]);if($dup->fetchColumn()){$error='This serial number is already listed as Faulty.';}else{$stmt=$conn->prepare("INSERT INTO faulty_devices (model,serial_number,cargo_number,issue,place,shop,status,added_by) VALUES (:model,:serial,:cargo,:issue,:place,:shop,'Faulty',:added_by)");$stmt->execute(['model'=>$model,'serial'=>$serial,'cargo'=>$cargo!==''?$cargo:null,'issue'=>$issue!==''?$issue:null,'place'=>$place!==''?$place:null,'shop'=>$shop,'added_by'=>$user_id]);try{$log=$conn->prepare("INSERT INTO activity_logs (user_id,action,details) VALUES (?,'Faulty Device - Add',?)");$log->execute([$user_id,"Added faulty device $serial ($model)"]);}catch(Throwable $ignored){}$success='Faulty device added successfully.';}}
}
?>
