ST['cargo_number']??'') ?>"></div><div class="field"><label>ISSUE</label><input name="issue" value="<?= htmlspecialchars($_POST['issue']??'') ?>"></div><div class="field"><label>PLACE</label><input name="place" value="<?= htmlspecialchars($_POST['place']??'') ?>"></div><div class="field"><label>SHOP</label><input name="shop" required value="<?= htmlspecialchars($_POST['shop']??'') ?>" placeholder="Enter shop"></div></div><div class="actions"><button class="btn primary" type="submit">Save Device</button><a class="btn light" href="faulty_devices.php">Back</a></div></form></div></div></body></html>
